WITH sr_ordered AS (SELECT sr.sr_item_sk, sr.sr_returned_date_sk, sr.sr_return_quantity, sr.sr_return_amt, cd.cd_gender AS gender, ROW_NUMBER() OVER (PARTITION BY sr.sr_item_sk ORDER BY sr.sr_returned_date_sk) AS rn, AVG(sr.sr_return_amt) OVER (PARTITION BY sr.sr_item_sk ORDER BY sr.sr_returned_date_sk ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS rolling_avg_amt FROM store_returns sr LEFT JOIN customer_demographics cd ON sr.sr_cdemo_sk = cd.cd_demo_sk) SELECT item_sk, returned_date_sk, return_quantity, return_amt, gender, rolling_avg_amt, CASE WHEN return_amt > 1.5 * rolling_avg_amt THEN 'ABOVE_THRESHOLD' ELSE 'NORMAL' END AS return_flag, RANK() OVER (ORDER BY total_item_return_amt DESC) AS item_return_rank FROM (SELECT sr.sr_item_sk AS item_sk, sr.sr_returned_date_sk AS returned_date_sk, sr.sr_return_quantity AS return_quantity, sr.sr_return_amt AS return_amt, sr.gender, sr.rolling_avg_amt, SUM(sr.sr_return_amt) OVER (PARTITION BY sr.sr_item_sk) AS total_item_return_amt, sr.rn FROM sr_ordered sr) t WHERE rn <= 10 ORDER BY item_sk, returned_date_sk
